CREATE TABLE site_content (
  id SMALLINT PRIMARY KEY CHECK (id = 1),
  content_json JSONB NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE admin_credentials (
  username VARCHAR(64) PRIMARY KEY,
  password_salt CHAR(32) NOT NULL,
  password_hash CHAR(128) NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE admin_sessions (
  id SMALLINT PRIMARY KEY CHECK (id = 1),
  token_hash CHAR(64) NOT NULL,
  expires_at BIGINT NOT NULL
);

CREATE TABLE admin_login_attempts (
  ip_hash CHAR(64) PRIMARY KEY,
  attempts SMALLINT NOT NULL,
  window_expires_at BIGINT NOT NULL,
  blocked_until BIGINT NOT NULL DEFAULT 0
);

INSERT INTO site_content (id, content_json)
VALUES (1, $portfolio_seed${"projects":[{"id":"loop","title":"Loop","subtitle":"Laravel mimarisiyle geliştirilen Sosyal Medya.","category":"Sosyal Medya Uygulaması","status":"Yapım Aşamasında","date":"","url":"https://github.com/ibrahimdvn/loop","summary":"LOOP, kullanıcıların içeriklerini özgürce paylaşabildiği, keşfedebildiği ve etkileşim kurabildiği modern bir sosyal medya platformudur. Kullanıcı deneyimi, içerik paylaşımı ve topluluk etkileşimini merkeze alan proje, sosyal medyaya farklı bir yaklaşım sunmayı hedefler.","description":"LOOP, kullanıcıların içerik oluşturabildiği, paylaşabildiği, keşfedebildiği ve diğer kullanıcılarla etkileşim kurabildiği kapsamlı bir sosyal medya platformu projesidir.\n\nModern sosyal ağların temel özelliklerini bir araya getiren platform; fotoğraf ve video paylaşımı, hikâyeler, kısa video akışı, kullanıcı profilleri, takip sistemi, doğrudan mesajlaşma, bildirimler ve içerik keşfi gibi işlevleri tek bir dijital ekosistem içerisinde sunmayı amaçlar.\n\nKullanıcı deneyiminin merkezinde içerik üretimi ve sosyal etkileşim yer alır. Kullanıcılar kendi profillerini oluşturabilir, içeriklerini paylaşabilir, diğer kullanıcıları takip edebilir, gönderilere yorum yapabilir ve beğeniler aracılığıyla etkileşim kurabilir. Arama ve trend sistemleri sayesinde yeni kullanıcıların, içeriklerin ve ilgi alanlarının keşfedilmesi hedeflenir.\n\nProje, yalnızca kullanıcı arayüzünden oluşan bir uygulama olarak değil; kullanıcı yönetimi, içerik işleme, medya optimizasyonu, veri ilişkileri, önbellekleme, arama ve gerçek zamanlı iletişim gibi farklı teknik bileşenleri bir araya getiren bir web uygulaması olarak geliştirilmiştir.\n\nTeknolojiler: PHP, Laravel, JavaScript, Bootstrap, Vite, Laravel Echo, Pusher ve Laravel Scout.\n\nLOOP''un vizyonu, kullanıcıların içeriklerini özgürce paylaşabildiği, dijital topluluklar oluşturabildiği ve sosyal etkileşimi tek bir platform üzerinden sürdürebildiği bütünleşik bir sosyal medya deneyimi geliştirmektir.","principles":["Kullanıcıların özgürce içerik oluşturup paylaşabileceği bir sosyal medya ortamı sunmak.","İçerik üretimini ve kullanıcı etkileşimini platformun merkezine yerleştirmek.","Fotoğraf, video, hikâye ve kısa video gibi farklı içerik formatlarını desteklemek.","Kullanıcıların birbirlerini takip ederek kendi sosyal çevrelerini oluşturmasını sağlamak.","Beğeni, yorum ve mesajlaşma özellikleriyle sosyal iletişimi güçlendirmek.","Arama ve keşif mekanizmalarıyla yeni kullanıcıların ve içeriklerin bulunmasını kolaylaştırmak.","Trend konular ve kişiselleştirilmiş öneriler aracılığıyla içerik keşfini geliştirmek.","Gerçek zamanlı bildirim ve mesajlaşma özellikleriyle etkileşimi kesintisiz hâle getirmek.","Kullanıcı deneyimini performans, erişilebilirlik ve işlevsellik açısından geliştirmek.","Farklı sosyal medya işlevlerini tek ve bütünleşik bir dijital platformda bir araya getirmek."],"titleEn":"Loop","subtitleEn":"A Social Media developed using the Laravel framework","categoryEn":"Social Media App","statusEn":"In Production","summaryEn":"LOOP is a modern social media platform where users can freely share, discover, and engage with content. With a focus on user experience, content sharing, and community interaction, the project aims to offer a different approach to social media.","descriptionEn":"LOOP is a comprehensive social media platform project where users can create, share, and discover content, as well as interact with other users.\n\nBringing together the core features of modern social networks, the platform aims to offer functions such as photo and video sharing, stories, short-form video feeds, user profiles, a following system, direct messaging, notifications, and content discovery—all within a single digital ecosystem.\n\nContent creation and social interaction are at the heart of the user experience. Users can create their own profiles, share content, follow other users, comment on posts, and interact through likes. The search and trending systems are designed to help users discover new users, content, and interests.\n\nThe project was developed not merely as an application consisting solely of a user interface, but as a web application that integrates various technical components, including user management, content processing, media optimization, data relationships, caching, search, and real-time communication.\n\nTechnologies: PHP, Laravel, JavaScript, Bootstrap, Vite, Laravel Echo, Pusher, and Laravel Scout.\n\nLOOP’s vision is to develop an integrated social media experience where users can freely share their content, build digital communities, and engage in social interaction all through a single platform.","principlesEn":["To provide a social media environment where users can freely create and share content.","To place content creation and user interaction at the heart of the platform.","Supporting various content formats such as photos, videos, stories, and short videos.","Enabling users to build their own social circles by following one another.","Strengthening social interaction through likes, comments, and messaging features.","Facilitating the discovery of new users and content through search and discovery mechanisms.","To enhance content discovery through trending topics and personalized recommendations.","To make interaction seamless with real-time notifications and messaging features.","To improve the user experience in terms of performance, accessibility, and functionality.","To bring together various social media functions on a single, integrated digital platform."]},{"id":"cinescope","title":"CineScope","subtitle":"Film ve dizi keşfini sosyal etkileşimle buluşturan dijital platform.","category":"Dizi/Film Uygulaması","status":"Yapım Aşamasında","date":"","url":"https://github.com/ibrahimdvn/CineScope","summary":"CineScope, TMDB API entegrasyonu sayesinde güncel film ve dizileri keşfetmeyi, favorilere eklemeyi, puanlamayı ve diğer kullanıcılarla paylaşım yaparak etkileşim kurmayı sağlayan Laravel tabanlı sosyal film ve dizi platformudur.","description":"CineScope, film ve dizi tutkunlarının içerik keşfedebileceği, yapımları takip edebileceği ve ortak ilgi alanları üzerinden etkileşim kurabileceği modern bir sosyal platformdur.\n\nLaravel altyapısıyla geliştirilen proje, TMDB (The Movie Database) API entegrasyonu sayesinde popüler, güncel ve vizyondaki film ve dizilere ait verileri kullanıcılarla buluşturur. Gelişmiş arama sistemi sayesinde kullanıcılar ilgilendikleri yapımları kolayca bulabilir, detaylarını inceleyebilir ve beğendikleri içerikleri kişisel favori listelerine ekleyebilir.\n\nCineScope yalnızca bir film ve dizi keşif platformu olmanın ötesinde, kullanıcı etkileşimini de merkeze alır. Sosyal akış sistemi üzerinden kullanıcılar gönderi paylaşabilir, film ve diziler hakkında değerlendirmelerde bulunabilir, beğeni ve yorumlarla tartışmalara katılabilir. Beş yıldızlı puanlama sistemi ve içerik etiketleme özellikleri, paylaşımları doğrudan ilgili yapımlarla ilişkilendirir.\n\nPlatformda yer alan bildirim sistemi, kullanıcıların gönderilerine gelen etkileşimleri takip etmelerini sağlarken yönetim paneli de kullanıcıların, içeriklerin ve sistem ayarlarının merkezi biçimde yönetilmesine imkân tanır.\n\nTeknolojik altyapısında Laravel 10, PHP, Blade, JavaScript, Vanilla CSS ve MySQL/SQLite kullanan CineScope; duyarlı tasarımı, koyu temalı arayüzü ve bütünleşik sosyal özellikleriyle film ve dizi deneyimini tek bir dijital ortamda bir araya getirir.\n\nCineScope''un temel amacı; film ve dizi keşfini, kişisel içerik takibini ve topluluk etkileşimini birleştirerek kullanıcıların yalnızca ne izleyeceklerini bulmalarını değil, izledikleri yapımlar hakkında paylaşım yapabilecekleri bir topluluğun parçası olmalarını sağlamaktır.","principles":["Kullanıcılara film ve dizileri keşfedebilecekleri merkezi bir dijital platform sunmak.","Güncel ve popüler film ve dizi verilerini TMDB API aracılığıyla kullanıcılarla buluşturmak.","Film ve dizilerin aranmasını, incelenmesini ve takip edilmesini kolaylaştırmak.","Kullanıcıların beğendikleri yapımları favorilerine ekleyerek kişisel listeler oluşturmasını sağlamak.","Film ve dizi tutkunlarının ortak ilgi alanları üzerinden etkileşim kurabileceği sosyal bir ortam oluşturmak.","Kullanıcıların film ve diziler hakkında gönderi paylaşmasını sağlamak.","Paylaşımlara yorum yapma ve beğenme özellikleriyle topluluk etkileşimini desteklemek.","Kullanıcıların yapımlara beş yıldızlı puan vererek görüşlerini paylaşmasına olanak tanımak.","Film ve dizileri sosyal paylaşımlarla ilişkilendirerek içerik etrafında tartışma ortamı oluşturmak.","Bildirim sistemiyle kullanıcılara gönderilerine gelen beğeni ve yorumları takip etme imkânı sunmak.","Kullanıcı hesaplarını ve platform içeriklerini yönetilebilir bir sistem içerisinde düzenlemek.","Yönetim paneli aracılığıyla kullanıcı, içerik ve sistem ayarlarının kontrolünü sağlamak.","Şifre sıfırlama ve hesap doğrulama süreçleriyle kullanıcı hesaplarının yönetimini desteklemek.","Mobil uyumlu ve modern arayüz tasarımıyla farklı cihazlarda tutarlı bir deneyim sunmak.","Film ve dizi keşfini, kişisel takip sistemini ve sosyal etkileşimi tek bir platformda birleştirmek."],"titleEn":"CineScope","subtitleEn":"A digital platform that combines movie and TV show discovery with social interaction.","categoryEn":"TV Show/Movie App","statusEn":"In Production","summaryEn":"CineScope is a Laravel-based social movie and TV series platform that, thanks to its TMDB API integration, allows users to discover the latest movies and TV series, add them to their favorites, rate them, and interact with other users by sharing content.","descriptionEn":"CineScope is a modern social platform where movie and TV series enthusiasts can discover content, follow productions, and connect with others based on shared interests.\n\nBuilt on the Laravel framework, the project uses TMDB (The Movie Database) API integration to provide users with data on popular, current, and upcoming movies and TV shows. Thanks to its advanced search system, users can easily find productions they’re interested in, explore their details, and add content they like to their personal favorites lists.\n\nCineScope goes beyond being just a movie and TV show discovery platform; it also places user interaction at the center. Through the social feed system, users can share posts, review movies and TV shows, and participate in discussions via likes and comments. The five-star rating system and content tagging features directly link posts to the relevant productions.\n\nThe platform’s notification system allows users to track interactions on their posts, while the admin panel enables centralized management of users, content, and system settings.\n\nBuilt on a technological infrastructure using Laravel 10, PHP, Blade, JavaScript, Vanilla CSS, and MySQL/SQLite, CineScope brings together the movie and TV series experience in a single digital environment with its responsive design, dark-themed interface, and integrated social features.\n\nCineScope’s primary goal is to combine movie and TV show discovery, personalized content tracking, and community interaction—ensuring users not only find what to watch but also become part of a community where they can share their thoughts on the shows they’ve watched.","principlesEn":["To provide users with a central digital platform where they can discover movies and TV shows.","To provide users with up-to-date and popular movie and TV show data via the TMDB API.","To make it easier to search for, explore, and keep track of movies and TV shows.","To allow users to create personal lists by adding productions they like to their favorites.","To create a social environment where movie and TV series enthusiasts can interact based on shared interests.","To enable users to share posts about movies and TV series.","To support community interaction through features that allow users to comment on and like posts.","To allow users to share their opinions by rating productions on a five-star scale.","Create a discussion forum around content by linking movies and TV shows to social shares.","Offer users the ability to track likes and comments on their posts through a notification system.","Organize user accounts and platform content within a manageable system.","Provide control over user, content, and system settings via the admin panel.","Support user account management through password reset and account verification processes.","Offer a consistent experience across different devices with a mobile-friendly and modern interface design.","Combine movie and TV show discovery, a personalized follow system, and social interaction into a single platform."]},{"id":"supportdesk","title":"SupportDesk","subtitle":"Destek süreçleri, yetkilendirme ve SLA takibi tek platformda.","category":"Destek Talepleri Uygulaması","status":"Tamamlandı.","date":"","url":"https://github.com/ibrahimdvn/supportdesk","summary":"SupportDesk, şirket içi destek süreçlerini ve müşteri taleplerini yönetmek için geliştirilmiş; rol tabanlı erişim kontrolü, SLA takibi, talep yönetimi ve Türkçe-İngilizce dil desteği sunan modern bir destek masası uygulamasıdır.","description":"SupportDesk, şirketlerin çalışanlarından veya müşterilerinden gelen destek taleplerini merkezi bir sistem üzerinden yönetebilmesi amacıyla geliştirilmiş, tam yığın (full-stack) bir destek masası uygulamasıdır. Proje; talep oluşturma, süreç takibi, kullanıcı rolleri, yetkilendirme ve hizmet seviyesi göstergelerini tek bir dijital platformda bir araya getirir.\n\nDestek Talebi ve Süreç Yönetimi\n\nUygulama, destek taleplerinin oluşturulmasını ve ilgili süreçlerin takip edilmesini sağlar. Talep detayları üzerinden yorumlar eklenebilir, işlem geçmişi görüntülenebilir ve taleplerin ilerleyişi izlenebilir. Yönetici yetkisine sahip kullanıcılar, gerekli durumlarda yorumları silebilir.\n\nKullanıcıların rol ve izinlerine göre talep durumu veya önceliği gibi alanlarda işlem yapabilmesi hedeflenmiştir. Böylece çalışanlar, destek personeli ve yöneticiler için farklı sorumluluk alanları oluşturulur.","principles":["Şirket içi destek ve müşteri taleplerini merkezi bir platform üzerinden yönetmek.","Destek taleplerinin oluşturulmasını, takip edilmesini ve sonuçlandırılmasını kolaylaştırmak.","Talep süreçlerini yorumlar ve işlem geçmişi aracılığıyla izlenebilir hâle getirmek.","Yönetici, destek personeli ve çalışan rolleri arasında yetki ayrımı oluşturmak.","Rol tabanlı erişim kontrolüyle kullanıcıların işlem yetkilerini düzenlemek.","Kullanıcılara özel izin değişiklikleri tanımlayabilecek esnek bir yetkilendirme yaklaşımı sunmak.","Talep durumu ve öncelik gibi kritik alanlarda yetkisiz değişiklikleri sınırlandırmak.","SLA uyumu ve yanıt süresi gibi operasyonel performans göstergelerini görünür kılmak.","Destek taleplerinin dağılımını ve sistem durumunu takip etmeyi kolaylaştırmak.","Türkçe ve İngilizce dil desteğiyle çok dilli kullanım imkânı sağlamak.","Kullanıcı arayüzünün farklı bölümlerinde tutarlı bir dil deneyimi sunmak.","Modern koyu tema ve glassmorphism tasarımıyla kullanıcı deneyimini geliştirmek.","Kimlik doğrulama ve parola güvenliği mekanizmalarıyla kullanıcı hesaplarını korumak.","Frontend ve backend katmanlarını API tabanlı bir mimariyle birbirinden ayırmak.","Destek operasyonlarını daha düzenli, kontrollü ve ölçülebilir bir yapıya dönüştürmek."],"titleEn":"SupportDesk","subtitleEn":"Support processes, authorization, and SLA tracking all on a single platform.","categoryEn":"Support Request Application","statusEn":"Completed","summaryEn":"SupportDesk is a modern help desk application developed to manage internal support processes and customer requests; it offers role-based access control, SLA tracking, request management, and support in both Turkish and English.","descriptionEn":"SupportDesk is a full-stack help desk application developed to enable companies to manage support requests from employees or customers through a centralized system. The project brings together request creation, process tracking, user roles, authorization, and service level indicators on a single digital platform.\n\nSupport Request and Process Management\n\nThe application enables the creation of support requests and the tracking of related processes. Comments can be added to request details, the action history can be viewed, and the progress of requests can be monitored. Users with administrative privileges can delete comments when necessary.\n\nThe system is designed to allow users to perform actions—such as setting request status or priority—based on their roles and permissions. This creates distinct areas of responsibility for employees, support staff, and managers.","principlesEn":["Manage internal support and customer requests through a centralized platform.","Streamline the creation, tracking, and resolution of support requests.","Make request processes traceable through comments and transaction history.","Establish a separation of duties among manager, support staff, and employee roles.","Regulate users’ transaction permissions through role-based access control.","Offer a flexible authorization approach that allows for user-specific permission changes.","Restrict unauthorized changes in critical areas such as request status and priority.","Make operational performance metrics, such as SLA compliance and response time, visible.","Facilitate tracking the distribution of support requests and system status.","Provide multilingual support with Turkish and English language options.","Deliver a consistent language experience across different sections of the user interface.","Enhance the user experience with a modern dark theme and glassmorphism design.","Protect user accounts with authentication and password security mechanisms.","Separate the frontend and backend layers using an API-based architecture.","Transform support operations into a more organized, controlled, and measurable structure."]},{"id":"skycast","title":"SkyCast","subtitle":"Hava durumunu anlık takip edin, geleceği önceden planlayın.","category":"Hava Durumu Uygulaması","status":"Tamamlandı.","date":"","url":"https://github.com/ibrahimdvn/SkyCast","summary":"SkyCast, Open-Meteo API entegrasyonu aracılığıyla dünya genelindeki şehirlerin güncel hava durumu verilerini, saatlik tahminlerini ve beş günlük hava tahminlerini sunan Laravel tabanlı bir hava durumu platformudur. Kullanıcılar şehir arayabilir, favori konumlarını kaydedebilir ve meteorolojik koşull","description":"SkyCast, dünya genelindeki hava durumu verilerini erişilebilir, anlaşılır ve görsel açıdan zengin bir deneyimle sunmak amacıyla geliştirilmiş Laravel tabanlı bir meteoroloji platformudur.\n\nProje, Open-Meteo API entegrasyonu sayesinde farklı şehirlerin güncel hava koşullarını, saatlik tahminlerini ve beş günlük hava durumu öngörülerini kullanıcılarla buluşturur. Open-Meteo Geocoding API aracılığıyla şehir isimleri koordinatlara dönüştürülerek ilgili konumun meteorolojik verileri alınır.\n\nPlatformun hava durumu panelinde sıcaklık, hissedilen sıcaklık, nem, rüzgâr hızı, görüş mesafesi, atmosfer basıncı ve bulutluluk oranı gibi temel meteorolojik göstergeler görüntülenir. Ayrıca 24 saatlik saatlik tahmin grafiği, yağış olasılığı, güneşin doğuş ve batış saatleri ile beş günlük genişletilmiş tahmin bölümü sunulur.\n\nKullanıcılar dünya genelinde şehir araması yapabilir, sık takip ettikleri konumları favorilerine ekleyebilir ve son aramalarına erişebilir. Favori şehirler kullanıcı hesabına bağlı olarak saklanır. Böylece kişisel hava durumu takibi daha düzenli hâle gelir.\n\nSkyCast, kullanıcı hesaplarının yönetimi için kayıt, giriş ve çıkış işlemlerini içeren özel bir kimlik doğrulama sistemi kullanır. Oturum tabanlı kimlik doğrulama, korumalı dashboard erişimi ve form doğrulama mekanizmalarıyla kullanıcı işlemleri yönetilir.\n\nProjenin görsel tasarımında glassmorphism yaklaşımı benimsenmiştir. Hava koşullarına ve günün saatine göre değişen dinamik arka planlar, modern kart tasarımları ve duyarlı sayfa düzeniyle farklı cihazlarda tutarlı bir deneyim hedeflenmiştir.\n\nTeknoloji altyapısı:  Laravel 10, PHP, Blade Templates, Tailwind CSS, JavaScript, MySQL/SQLite, Open-Meteo Weather API ve Open-Meteo Geocoding API.\n\nSkyCast''in temel amacı, güncel meteorolojik verileri şehir arama, kişisel konum takibi ve kapsamlı hava tahminleriyle birleştirerek kullanıcıların hava koşullarını kolayca takip edebileceği bütünleşik bir dijital platform oluşturmaktır.","principles":["Dünya genelindeki şehirlerin hava durumu verilerine erişim sağlayan bir platform sunmak.","Güncel meteorolojik verileri Open-Meteo API aracılığıyla kullanıcılara ulaştırmak.","Şehir arama ve coğrafi konum belirleme mekanizmalarıyla farklı bölgelerin hava durumunu görüntülemek.","Anlık sıcaklık, hissedilen sıcaklık ve temel hava koşullarını kullanıcılarla paylaşmak.","Nem, rüzgâr, görüş mesafesi, atmosfer basıncı ve bulutluluk gibi meteorolojik göstergeleri sunmak.","24 saatlik saatlik hava tahminleriyle kısa vadeli hava değişimlerini takip etmeyi kolaylaştırmak.","Yağış olasılığı verileriyle kullanıcıların günlük planlarını desteklemek.","Beş günlük hava tahminiyle orta vadeli meteorolojik görünürlük sağlamak.","Güneşin doğuş ve batış saatlerini görsel bir gösterge üzerinden sunmak.","Kullanıcıların sık takip ettikleri şehirleri favorilerine ekleyebilmesini sağlamak.","Son aramaları saklayarak şehirler arasında yeniden arama yapmayı kolaylaştırmak.","Kullanıcı hesapları üzerinden kişisel favori şehir listeleri oluşturmak.","Kayıt, giriş ve oturum yönetimi özellikleriyle kişiselleştirilmiş bir kullanım deneyimi sunmak.","Hava koşullarına ve günün saatine göre değişen dinamik arka planlar kullanmak.","Glassmorphism tasarım yaklaşımıyla modern ve görsel açıdan tutarlı bir arayüz oluşturmak.","Mobil cihazlar ve masaüstü ekranlar için duyarlı tasarım sunmak.","Laravel önbellekleme mekanizmasıyla API isteklerini optimize etmek ve gereksiz veri çağrılarını azaltmak.","Meteorolojik verileri, kişisel konum takibini ve hava tahminlerini tek bir dijital platformda birleştirmek."],"titleEn":"SkyCast","subtitleEn":"Keep track of the weather in real time and plan ahead.","categoryEn":"Wheather App","statusEn":"Completed","summaryEn":"SkyCast is a Laravel-based weather platform that provides real-time weather data, hourly forecasts, and five-day weather forecasts for cities around the world through its integration with the Open-Meteo API. Users can search for cities, save their favorite locations.","descriptionEn":"SkyCast is a Laravel-based meteorology platform developed to present global weather data through an accessible, easy-to-understand, and visually rich experience.\n\nThanks to its integration with the Open-Meteo API, the project provides users with current weather conditions, hourly forecasts, and five-day weather forecasts for various cities. City names are converted into coordinates via the Open-Meteo Geocoding API to retrieve meteorological data for the relevant location.\n\nThe platform’s weather dashboard displays key meteorological indicators such as temperature, feels-like temperature, humidity, wind speed, visibility, atmospheric pressure, and cloud cover. It also features a 24-hour hourly forecast graph, precipitation probability, sunrise and sunset times, and a five-day extended forecast section.\n\nUsers can search for cities worldwide, add frequently tracked locations to their favorites, and access their recent searches. Favorite cities are saved based on the user’s account, making personal weather tracking more organized.\n\nSkyCast uses a dedicated authentication system for user account management, including registration, login, and logout processes. User operations are managed through session-based authentication, secure dashboard access, and form validation mechanisms.\n\nThe project’s visual design adopts the glassmorphism approach. Dynamic backgrounds that change based on weather conditions and the time of day, modern card designs, and a responsive page layout aim to provide a consistent experience across different devices.\n\nTechnology stack: Laravel 10, PHP, Blade Templates, Tailwind CSS, JavaScript, MySQL/SQLite, Open-Meteo Weather API, and Open-Meteo Geocoding API.","principlesEn":["To provide a platform that offers access to weather data for cities around the world.","Deliver up-to-date meteorological data to users via the Open-Meteo API.","Display weather conditions for different regions using city search and geolocation mechanisms.","Share real-time temperature, feels-like temperature, and basic weather conditions with users.","Provide meteorological indicators such as humidity, wind, visibility, atmospheric pressure, and cloud cover.","To make it easier to track short-term weather changes with 24-hour hourly forecasts.","To support users’ daily plans with precipitation probability data.","To provide medium-term weather visibility with a five-day forecast.","To display sunrise and sunset times via a visual indicator.","To allow users to add cities they frequently track to their favorites.","To make it easier to search for cities again by saving recent searches.","To allow users to create personal lists of favorite cities through their user accounts.","To offer a personalized user experience with registration, login, and session management features.","To use dynamic backgrounds that change based on weather conditions and the time of day.","To create a modern and visually consistent interface using the Glassmorphism design approach.","Provide a responsive design for mobile devices and desktop screens.","Optimize API requests and reduce unnecessary data calls using Laravel’s caching mechanism.","Integrate meteorological data, personal location tracking, and weather forecasts into a single digital platform."]}],"notes":[{"id":"1","title":"Bilim ve Teknoloji: Evreni Anlamak ve Geleceği İnşa Etmek","category":"Bilim ve Teknoloji","date":"11/11/2026","readingTime":"5 dk okuma","summary":"Bilim ve teknolojiye olan merakımı; evrenin işleyişinden insan zihnine, fiziksel yasalardan yapay zekâya kadar uzanan araştırmalarla besliyorum. Amacım, dünyayı anlamak, yeni bilgiler keşfetmek ve bilginin geleceği nasıl şekillendirdiğini sorgulamak.","body":"Bilim, benim için yalnızca bilgi edinmenin değil, içinde yaşadığımız dünyayı anlamlandırmanın da en güçlü yollarından biri. Evrenin oluşumundan maddenin temel yapısına, insan beyninin çalışma mekanizmalarından teknolojik gelişmelere kadar uzanan geniş bir araştırma alanı, sürekli yeni sorular sormama neden oluyor.\n\nBilimin en ilgi çekici yönlerinden biri, görünürde birbirinden bağımsız olan olayların aslında ortak fiziksel ve matematiksel ilkelerle açıklanabilmesi. Astronomi, fizik, biyoloji, nörobilim ve bilgisayar bilimleri gibi farklı disiplinlerin birbirleriyle kurduğu ilişkiler, doğayı daha bütüncül bir bakış açısıyla değerlendirmemi sağlıyor.\n\nTeknoloji ise bilimsel bilginin uygulamaya dönüşmüş hâli olarak ilgimi çekiyor. Yapay zekâ, yazılım mühendisliği, veri sistemleri ve bilgisayar teknolojileri, insanlığın problem çözme kapasitesini sürekli genişletiyor. Özellikle teknolojinin yalnızca mevcut sorunları çözmekle kalmayıp daha önce mümkün olmayan yeni imkânlar yaratması dikkatimi çekiyor.\n\nBu alanlara yaklaşımımda ezberlemekten çok anlamaya, hazır cevapları kabul etmekten çok sorgulamaya önem veriyorum. Çünkü bilimsel düşüncenin temelinde merak, gözlem, deney ve sürekli sorgulama bulunuyor.\n\nBilim ve teknoloji üzerine yaptığım araştırmaları, dünyayı daha iyi anlamak ve geleceğin nasıl şekillendiğini takip etmek için sürdürmek istiyorum. Benim için öğrenme, belirli bir noktada tamamlanan bir süreç değil; her yeni bilgiyle genişleyen sürekli bir keşif yolculuğu.","titleEn":"Science and Technology: Understanding the Universe and Shaping the Future","categoryEn":"Science and Technology","readingTimeEn":"5 Min. Read","summaryEn":"I nurture my curiosity about science and technology through research that spans from the workings of the universe to the human mind, and from the laws of physics to artificial intelligence. My goal is to understand the world, discover new knowledge, and explore how knowledge shapes the future.","bodyEn":"For me, science is not only a way to acquire knowledge but also one of the most powerful ways to make sense of the world we live in. A broad field of research ranging from the formation of the universe to the fundamental structure of matter, and from the mechanisms of the human brain to technological advancements constantly inspires me to ask new questions.\n\nOne of the most fascinating aspects of science is that events which appear to be independent of one another can actually be explained by common physical and mathematical principles. The connections between different disciplines such as astronomy, physics, biology, neuroscience, and computer science allow me to view nature from a more holistic perspective.\n\nTechnology, on the other hand, captures my interest as the practical application of scientific knowledge. Artificial intelligence, software engineering, data systems, and computer technologies are constantly expanding humanity’s problem-solving capacity. I am particularly drawn to the fact that technology not only solves existing problems but also creates new possibilities that were previously unimaginable.\n\nIn my approach to these fields, I prioritize understanding over memorization and questioning over accepting ready-made answers. This is because curiosity, observation, experimentation, and constant questioning lie at the heart of scientific thinking.\n\nI want to continue my research on science and technology to better understand the world and keep track of how the future is taking shape. For me, learning is not a process that ends at a specific point; it is a continuous journey of discovery that expands with every new piece of knowledge."},{"id":"2","title":"Havacılık ve Uzay: Gökyüzünden Evrenin Derinliklerine","category":"Havacılık ve Astronomi","date":"11/11/2026","readingTime":"5 dk okuma","summary":"Havacılık ve uzay bilimlerine olan ilgim, uçuşun ardındaki fiziksel prensiplerden uzayın derinliklerindeki keşiflere kadar uzanıyor. Aerodinamik, uçuş mekaniği, havacılık teknolojileri ve uzay araştırmaları üzerine öğrenmeye, keşfetmeye odaklanıyorum.","body":"İnsanlığın gökyüzüne ulaşma ve Dünya''nın ötesini keşfetme arzusu, bilim ve mühendislik tarihinin en önemli gelişmelerinden bazılarına öncülük etti. Havacılık ve uzay teknolojileri, bu merakın matematik, fizik ve mühendislikle birleşerek somut başarılara dönüşmesinin en etkileyici örneklerinden biri.\n\nHavacılık alanında beni özellikle ilgilendiren konuların başında aerodinamik, uçuş mekaniği, motor sistemleri ve uçakların çalışma prensipleri geliyor. Bir uçağın havada kalabilmesi; kaldırma kuvveti, ağırlık, itki ve sürükleme gibi temel fiziksel kuvvetlerin dengeli etkileşimine dayanıyor. Bu mekanizmaların arkasındaki bilimsel prensipleri anlamak, uçuşun yalnızca teknolojik değil, aynı zamanda fiziksel açıdan da ne kadar karmaşık bir sistem olduğunu gösteriyor.\n\nUzay araştırmaları ise bu merakı çok daha geniş bir boyuta taşıyor. Roket teknolojileri, yörünge mekaniği, uydu sistemleri, gezegen araştırmaları ve derin uzay görevleri, insanlığın Dünya dışındaki varlığını anlamlandırma çabasının önemli parçaları. Özellikle evrenin yapısı, gezegenlerin oluşumu ve başka gök cisimlerinde yaşam ihtimali üzerine yapılan araştırmalar ilgimi çekiyor.\n\nHavacılık ve uzay bilimlerini benim için özel kılan nokta, teorik bilginin mühendislik yoluyla olağanüstü sistemlere dönüşebilmesi. Bir uçağın tasarımından uzay aracının yörüngeye yerleştirilmesine kadar her aşamada matematiksel hesaplamalar, fiziksel yasalar ve ileri mühendislik çözümleri birlikte çalışıyor.\n\nBu alanlarda öğrenmeye devam ederken yalnızca teknolojik gelişmeleri takip etmek değil, bu gelişmelerin arkasındaki bilimsel mantığı da kavramak istiyorum. Çünkü gökyüzünü anlamak, aslında evreni anlama yolculuğunun ilk adımlarından biri.","titleEn":"Aviation and Space: From the Sky to the Depths of the Universe","categoryEn":"Aviation and Astronomy","readingTimeEn":"5 Min. Read","summaryEn":"My interest in aviation and space sciences ranges from the physical principles behind flight to explorations in the depths of space. I focus on learning and exploring aerodynamics, flight mechanics, aviation technologies, and space research.","bodyEn":"Humanity’s desire to reach the skies and explore beyond Earth has spearheaded some of the most significant developments in the history of science and engineering. Aviation and space technologies are among the most impressive examples of how this curiosity, combined with mathematics, physics, and engineering, has led to tangible achievements.\n\nAmong the topics that particularly interest me in the field of aviation are aerodynamics, flight mechanics, engine systems, and the operating principles of aircraft. An aircraft’s ability to remain airborne depends on the balanced interaction of fundamental physical forces such as lift, weight, thrust, and drag. Understanding the scientific principles behind these mechanisms reveals just how complex a system flight is—not only from a technological perspective but also from a physical one.\n\nSpace exploration, on the other hand, takes this curiosity to a much broader scale. Rocket technologies, orbital mechanics, satellite systems, planetary research, and deep-space missions are all crucial components of humanity’s effort to make sense of our existence beyond Earth. I am particularly drawn to research on the structure of the universe, the formation of planets, and the possibility of life on other celestial bodies.\n\nWhat makes aerospace science special to me is how theoretical knowledge can be transformed into extraordinary systems through engineering. From the design of an airplane to the deployment of a spacecraft into orbit, mathematical calculations, physical laws, and advanced engineering solutions work together at every stage.\n\nAs I continue to learn in these fields, I want to do more than just keep up with technological advancements—I want to understand the scientific logic behind them. Because understanding the sky is actually one of the first steps on the journey to understanding the universe."}]}$portfolio_seed$::jsonb)
ON CONFLICT (id) DO NOTHING;
